using System.Linq;
internal sealed class JagoWorkspaceClient {
 readonly System.Windows.Forms.Form form;readonly Microsoft.Web.WebView2.Core.CoreWebView2 core;
 readonly System.Web.Script.Serialization.JavaScriptSerializer json=new System.Web.Script.Serialization.JavaScriptSerializer{MaxJsonLength=200000000,RecursionLimit=512};
 readonly string folder,workspaceRoot;bool detachedWindow;System.Windows.Forms.Timer timer;bool busy,initialized,active=true,stopped;int ticks;
 [System.Runtime.InteropServices.DllImport("user32.dll")]static extern System.IntPtr SetParent(System.IntPtr child,System.IntPtr parent);
 [System.Runtime.InteropServices.DllImport("user32.dll",EntryPoint="SetWindowLongPtrW")]static extern System.IntPtr SetStyle(System.IntPtr child,int index,System.IntPtr value);
 [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool MoveWindow(System.IntPtr h,int x,int y,int w,int height,bool repaint);
 internal JagoWorkspaceClient(System.Windows.Forms.Form window,Microsoft.Web.WebView2.Core.CoreWebView2 browser){form=window;core=browser;folder=System.Environment.GetEnvironmentVariable("JAGO_WORKSPACE_TAB_ROOT");workspaceRoot=System.Environment.GetEnvironmentVariable("JAGO_WORKSPACE_ROOT");if(folder==null)return;System.IO.Directory.CreateDirectory(folder);timer=new System.Windows.Forms.Timer{Interval=500};timer.Tick+=async(s,e)=>await Tick();timer.Start();form.FormClosed+=(s,e)=>{stopped=true;timer.Stop();timer.Dispose();};}
 static void Atomic(string path,string text){string temp=path+".tmp";System.IO.File.WriteAllText(temp,text);if(System.IO.File.Exists(path))System.IO.File.Replace(temp,path,null);else System.IO.File.Move(temp,path);}
 async System.Threading.Tasks.Task Suspend(){try{await core.TrySuspendAsync();}catch(System.InvalidOperationException){/* Some runtimes decline suspension; the studio scripts are already paused. */}}
 async System.Threading.Tasks.Task Tick(){if(busy||stopped||form.IsDisposed)return;busy=true;try{
 if(!initialized){if(await core.ExecuteScriptAsync("!!window.JagoSession && !!window.JagoSuite?.adapter")=="true"){string recover=System.IO.Path.Combine(folder,"restore.json");if(System.IO.File.Exists(recover)){string data=JagoHostSecurity.JsonArgument(recover,200000000);await core.ExecuteScriptAsync("window.__workspaceRestore=null;JagoSession.restore("+data+").then(()=>window.__workspaceRestore={ok:true}).catch(e=>window.__workspaceRestore={error:e.message})");string restoreStatus="null";for(int wait=0;wait<300;wait++){restoreStatus=await core.ExecuteScriptAsync("window.__workspaceRestore");if(restoreStatus!="null")break;await System.Threading.Tasks.Task.Delay(50);}if(restoreStatus=="null")throw new System.Exception("The document is still restoring. Please retry.");var restoreResult=json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(restoreStatus);if(restoreResult.ContainsKey("error"))throw new System.Exception(System.Convert.ToString(restoreResult["error"]));System.IO.File.Move(recover,System.IO.Path.Combine(folder,"restored-"+System.Guid.NewGuid()+".json"));}initialized=true;Atomic(System.IO.Path.Combine(folder,"ready.json"),json.Serialize(new{ready=true,handle=form.Handle.ToInt64()}));}else return;}
 foreach(string path in System.IO.Directory.GetFiles(folder,"command-*.json").OrderBy(f=>f)){System.Collections.Generic.Dictionary<string,object> m;try{m=json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(JagoHostSecurity.ReadBounded(path,2000000));if(m==null||!m.ContainsKey("type"))throw new System.IO.InvalidDataException("Missing command type.");}catch(System.Exception invalid){System.IO.File.Move(path,path+".invalid-"+System.Guid.NewGuid().ToString("N"));Atomic(System.IO.Path.Combine(folder,"error.txt"),"Ignored an invalid workspace command: "+invalid.Message);continue;}string type=System.Convert.ToString(m["type"]);System.IO.File.Delete(path);
 if(type=="attach"){detachedWindow=false;timer.Interval=500;System.Environment.SetEnvironmentVariable("JAGO_WORKSPACE_ROOT",workspaceRoot);core.Resume();form.Visible=true;form.FormBorderStyle=System.Windows.Forms.FormBorderStyle.None;form.MinimumSize=new System.Drawing.Size(0,0);SetParent(form.Handle,new System.IntPtr(System.Convert.ToInt64(m["parent"])));SetStyle(form.Handle,-16,new System.IntPtr(0x50000000L));MoveWindow(form.Handle,0,0,System.Convert.ToInt32(m["width"]),System.Convert.ToInt32(m["height"]),true);Atomic(System.IO.Path.Combine(folder,"attached.json"),json.Serialize(new{handle=form.Handle.ToInt64()}));}
 else if(type=="resize")MoveWindow(form.Handle,0,0,System.Convert.ToInt32(m["width"]),System.Convert.ToInt32(m["height"]),true);
 else if(type=="detach"){core.Resume();form.Visible=true;SetParent(form.Handle,System.IntPtr.Zero);SetStyle(form.Handle,-16,new System.IntPtr(0x10CF0000L));form.FormBorderStyle=System.Windows.Forms.FormBorderStyle.Sizable;form.Size=new System.Drawing.Size(1280,850);form.Activate();active=true;await core.ExecuteScriptAsync("JagoSession.focus(true)");System.Environment.SetEnvironmentVariable("JAGO_WORKSPACE_ROOT",null);Atomic(System.IO.Path.Combine(folder,"detached.json"),json.Serialize(new{handle=form.Handle.ToInt64()}));detachedWindow=true;timer.Interval=1500;}
 else if(type=="theme"){core.Resume();await core.ExecuteScriptAsync("window.JagoSharedThemes?.apply("+json.Serialize(m["name"])+")");string themeState=await core.ExecuteScriptAsync("JagoSession.status()");Atomic(System.IO.Path.Combine(folder,"state.json"),themeState);if(!active)await Suspend();}
 else if(type=="focus"){active=System.Convert.ToBoolean(m["active"]);if(active){core.Resume();await core.ExecuteScriptAsync("JagoSession.focus(true)");if(form.Controls.Count>0)form.Controls[0].Focus();}else{await core.ExecuteScriptAsync("JagoSession.focus(false)");await Suspend();}}
 else if(type=="test-preview"&&System.Environment.GetEnvironmentVariable("JAGO_WORKSPACE_TEST_ROOT")!=null){using(var file=System.IO.File.Create(System.IO.Path.Combine(System.Environment.GetEnvironmentVariable("JAGO_WORKSPACE_TEST_ROOT"),System.IO.Path.GetFileName(System.Convert.ToString(m["name"]))))){await core.CapturePreviewAsync(Microsoft.Web.WebView2.Core.CoreWebView2CapturePreviewImageFormat.Png,file);}}
 else if(type=="test"&&System.Environment.GetEnvironmentVariable("JAGO_WORKSPACE_TEST_ROOT")!=null){await core.ExecuteScriptAsync("window.__workspaceTestResult=null;"+System.Convert.ToString(m["script"]));string result="null";for(int i=0;i<300;i++){result=await core.ExecuteScriptAsync("window.__workspaceTestResult||null");if(result!="null")break;await System.Threading.Tasks.Task.Delay(50);}Atomic(System.IO.Path.Combine(folder,"test-result.json"),result);}
 else if(type=="shortcut"){core.Resume();await core.ExecuteScriptAsync("window.JagoWorkspaceShortcut("+json.Serialize(m["key"])+","+json.Serialize(m["shift"])+")");}
 else if(type=="capture"){core.Resume();string doc=await core.ExecuteScriptAsync("JagoSession.capture().then(x=>window.__workspaceCapture=x).catch(e=>window.__workspaceCapture={error:e.message})");for(int i=0;i<240;i++){doc=await core.ExecuteScriptAsync("window.__workspaceCapture||null");if(doc!="null")break;await System.Threading.Tasks.Task.Delay(50);}Atomic(System.IO.Path.Combine(folder,"snapshot.json"),doc);await core.ExecuteScriptAsync("window.__workspaceCapture=null");if(!active)await Suspend();}
 else if(type=="receive"){core.Resume();await core.ExecuteScriptAsync("JagoSuite.receive("+JagoHostSecurity.JsonArgument(System.Convert.ToString(m["path"]),110000000)+")");}
 else if(type=="close"){if(await core.ExecuteScriptAsync("JagoSession.status().pending")=="true")throw new System.Exception("Finish or cancel the current export before closing Pulse.");stopped=true;core.Resume();await core.ExecuteScriptAsync("window.checkUnsaved=()=>false;window.onbeforeunload=null;window.__workspaceConfirmedClose=true");timer.Stop();form.Close();return;}
 }
 if(active&&!detachedWindow&&ticks++%4==0){string inventory=System.IO.Path.Combine(System.Environment.GetEnvironmentVariable("JAGO_WORKSPACE_ROOT"),"inventory.json");if(System.IO.File.Exists(inventory))core.PostWebMessageAsJson("{\"type\":\"jago-workspace-inventory\",\"tabs\":"+System.IO.File.ReadAllText(inventory)+"}");string state=await core.ExecuteScriptAsync("JagoSession.status()");Atomic(System.IO.Path.Combine(folder,"state.json"),state);}
 }catch(System.Exception e){if(!stopped&&!form.IsDisposed)try{Atomic(System.IO.Path.Combine(folder,"error.txt"),e.ToString());}catch{}}finally{busy=false;}}
}
